mapper.select:
select generation_id, generation_code, generation_mode, input_amount, target_amount, generation_status, generation_remark, generated_count, started_time, finished_time, user_id, client_request_id, worker_id, lease_expire_time, attempt_count, max_attempts, next_retry_time, create_by, create_time, update_by, update_time from fx67ll_dortmund_return_generation
and generation_id = #{generationId}
and generation_status = #{generationStatus}
and generation_mode = #{generationMode} and user_id = #{userId}
and create_time between #{beginCreateTime} and #{endCreateTime}
order by create_time desc, generation_id desc
